<script setup>
import MobileDialog from './MobileDialog.vue';
import ProductImagePreview from '../ProductImagePreview.vue';
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue';
import {ElMessage} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import {useAuthStore} from '../../stores/auth.js';
import {shanghaiDateTimeText} from '../../utils/shanghai-date.js';
import {inventoryWorkflow} from '../../../../src/shared/inventory-workflow.js';
import {inventoryAdjustmentReasons} from '../../../../src/inventory-adjustment-reasons.js';
const props=defineProps({modelValue:Boolean,readOnly:Boolean,contextNote:String,product:{type:Object,default:()=>({})}}),emit=defineEmits(['update:modelValue','saved']);
const auth=useAuthStore();
const lastStocktake=computed(()=>[...(data.value?.actions||[])].sort((a,b)=>Number(b.id)-Number(a.id))[0]);
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)}),data=ref(null),preview=ref(null),submission=ref(null),error=ref(''),busy=ref(false),loading=ref(false),form=reactive({counted_quantity:null,reason_code:'',reason_note:''});let generation=0,disposed=false;
const availableBefore=computed(()=>data.value?inventoryWorkflow(data.value,{applications:[]}).free:null);
const availableAfter=computed(()=>data.value&&preview.value?inventoryWorkflow({...data.value,physical_estimate:preview.value.physical_after},{applications:[]}).free:null);
async function load(){const token=++generation,scope=currentApiCacheScope();loading.value=true;data.value=null;preview.value=null;submission.value=null;error.value='';Object.assign(form,{counted_quantity:null,reason_code:'',reason_note:''});try{const result=await apiClient.get(`/api/inventory/ledger?product_id=${props.product.id}&include_flow=local`,{noCache:true});if(!disposed&&token===generation&&scope===currentApiCacheScope())data.value=result;}catch(e){if(token===generation&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===generation)loading.value=false;}}
async function next(){if(form.counted_quantity==null||!Number.isSafeInteger(Number(form.counted_quantity))||Number(form.counted_quantity)<0)return ElMessage.warning('请填写实际清点数量，无货请填0');if(!form.reason_code)return ElMessage.warning('请选择调整原因');if(form.reason_code==='other'&&!form.reason_note.trim())return ElMessage.warning('请说明调整原因');const token=generation,scope=currentApiCacheScope();busy.value=true;error.value='';try{const payload={...form,counted_quantity:Number(form.counted_quantity),product_id:props.product.id,action_type:'stocktake',stocktake_type:'physical',revision:data.value.revision,request_key:crypto.randomUUID()};const result=await apiClient.post('/api/inventory/ledger/preview',payload);if(disposed||token!==generation||scope!==currentApiCacheScope())return;preview.value=result;submission.value=payload;}catch(e){if(token===generation&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===generation)busy.value=false;}}
async function save(){if(busy.value||!submission.value)return;const token=generation,scope=currentApiCacheScope();busy.value=true;error.value='';try{const result=await apiClient.post('/api/inventory/ledger',submission.value);if(disposed||token!==generation||scope!==currentApiCacheScope())return;ElMessage.success('本地实物已更新');emit('saved',result);visible.value=false;}catch(e){if(token===generation&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===generation)busy.value=false;}}
function clear(){++generation;data.value=null;submission.value=null;preview.value=null;visible.value=false;}
watch(()=>[props.modelValue,props.product.id],()=>{if(props.modelValue)load();else ++generation;},{immediate:true});window.addEventListener('erp:auth-scope-changed',clear);onBeforeUnmount(()=>{disposed=true;clear();window.removeEventListener('erp:auth-scope-changed',clear);});
</script>
<template><MobileDialog v-model="visible" class="mobile-dialog mobile-stocktake-dialog" :title="readOnly?'库存明细':preview?'确认盘点影响':'盘点本地库存'" append-to-body :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy"><div class="mobile-form" v-loading="loading"><div class="mobile-record-head"><ProductImagePreview :src="`/api/products/${product.id}/image?thumb=1`" :preview-list="[`/api/products/${product.id}/image`]" size="portrait"/><div><h3>{{product.name}}</h3><small class="mobile-muted">库存 {{product.inventory_number||product.code||product.id}}</small><el-tag size="small">{{Number(product.component_count)>0?'套装':Number(product.is_accessory)?'配件':'单品'}}</el-tag></div></div><el-alert v-if="error" :title="error" type="warning" :closable="false"/><template v-if="data"><small v-if="contextNote&&!readOnly" class="mobile-muted">{{contextNote}}</small><small v-if="!readOnly" class="mobile-muted">本次操作人：{{auth.user?.name||auth.user?.username}} · 自动记录时间、原因和数量变动</small><small v-if="lastStocktake" class="mobile-muted">最近核对：{{lastStocktake.person_name||'未记录姓名'}} · {{shanghaiDateTimeText(lastStocktake.created_at,{assumeUtcWhenNaive:true})}} · {{lastStocktake.reason}}</small><div class="mobile-record-grid"><span>本地实物<b>{{preview?.physical_before??data.physical_estimate??'待核实'}}<template v-if="preview"> → {{preview.physical_after}}</template></b></span><span>可用库存<b>{{availableBefore??'待核实'}}<template v-if="preview"> → {{availableAfter??'待核实'}}</template></b></span></div><template v-if="!preview&&!readOnly"><label>仓库实物总数（包含待发货品，不含在途和FBP）<input v-model.number="form.counted_quantity" type="number" inputmode="numeric" min="0" step="1" aria-label="实际清点数量" :disabled="busy"></label><label>调整原因<select v-model="form.reason_code" :disabled="busy" aria-label="调整原因"><option value="">请选择</option><option v-for="reason in inventoryAdjustmentReasons" :key="reason.code" :value="reason.code">{{reason.label}}</option></select></label><label>补充说明<textarea v-model="form.reason_note" maxlength="500" :disabled="busy"/></label></template><small class="mobile-muted">可用量沿用公共库存规则，扣除待发订单、安全保障和已锁定FBP；规则不完整时显示待核实。</small><p v-if="preview">实物差额 {{preview.stocktake_delta}} 件。{{preview.reason}}。确认后记录操作人和库存流水。</p><template v-if="readOnly"><small>FBS待发需求 {{data.open_order_demand??0}} 件 · FBP锁定 {{data.fbp_reserved??0}} 件 · 采购在途 {{data.incoming_quantity??0}} 件</small><article v-for="order in data.orders||[]" :key="order.order_item_id" class="mobile-record"><b>{{order.posting_number}}</b><small>需求 {{order.quantity}} 件 · 待采购 {{order.shortage_quantity}} 件</small></article></template></template></div><template #footer><el-button :disabled="busy" @click="visible=false">{{readOnly?'返回':'取消'}}</el-button><el-button v-if="preview" :disabled="busy" @click="preview=null;submission=null">返回修改</el-button><el-button v-if="!readOnly" type="primary" :disabled="loading||!data" :loading="busy" @click="preview?save():next()">{{preview?'确认更新':'预览变动'}}</el-button></template></MobileDialog></template>
